INSERT INTO courses (title_en,title_ar,title_ckb,title_badini,description_en,description_ar,description_ckb,description_badini,long_description_en,long_description_ar,long_description_ckb,long_description_badini,level,type,price_iqd,lessons_count) SELECT 'Responsive Web Design','تصميم المواقع المتجاوبة','دیزاینی ماڵپەڕی وەڵامدەر','Dîzayna malperê ya bersivdar','Build polished responsive pages with modern layouts and accessibility.','ابني صفحات ويب متجاوبة ومنظمة مع أساسيات الوصول وسهولة الاستخدام.','ماڵپەڕی وەڵامدەر بە شێوازی نوێ و دەستگەیشتن دروست بکە.','Malperên bersivdar bi şêwazê nû û gihiştinê ava bike.','A practical next step after HTML and CSS: responsive layouts, components, accessibility and a complete landing page project.','پاش بنەماکانی HTML وCSS، ڕێکخستنی وەڵامدەر، پێکهاتەکان، دەستگەیشتن و پڕۆژەیەکی تەواوی پەڕەی ناساندن فێر دەبیت.','دوای HTML و CSS، layout ـی وەڵامدەر، component و accessibility و پڕۆژەیەکی تەواو فێربە.','Piştî HTML û CSS, layoutên bersivdar, component, gihiştin û projeyek temam fêr bibe.','Beginner','free',0,12 FROM (SELECT 1) AS seed WHERE NOT EXISTS (SELECT 1 FROM courses WHERE title_en='Responsive Web Design');
INSERT INTO courses (title_en,title_ar,title_ckb,title_badini,description_en,description_ar,description_ckb,description_badini,long_description_en,long_description_ar,long_description_ckb,long_description_badini,level,type,price_iqd,lessons_count) SELECT 'PHP & MySQL for Beginners','PHP و MySQL للمبتدئات','PHP و MySQL بۆ دەستپێکەران','PHP û MySQL ji bo destpêkeran','Build dynamic websites with PHP and connect them to MySQL.','تعلّمي بناء مواقع ديناميكية باستخدام PHP وربطها بقاعدة بيانات MySQL.','ماڵپەڕی دینامیکی بە PHP دروست بکە و بە MySQL پەیوەندی بدە.','Malperên dînamîk bi PHP ava bike û bi MySQL ve girêde.','Learn forms, sessions, CRUD, database queries and a small dashboard project.','فێری فۆرمەکان، سێشنەکان، CRUD، پرسیارەکانی داتا و پڕۆژەی داشبۆردێکی بچووک دەبیت.','فۆرم، session، CRUD، query ـی داتا و داشبۆرد فێربە.','Form, session, CRUD, query û dashboard fêr bibe.','Intermediate','paid',30000,14 FROM (SELECT 1) AS seed WHERE NOT EXISTS (SELECT 1 FROM courses WHERE title_en='PHP & MySQL for Beginners');
INSERT INTO courses (title_en,title_ar,title_ckb,title_badini,description_en,description_ar,description_ckb,description_badini,long_description_en,long_description_ar,long_description_ckb,long_description_badini,level,type,price_iqd,lessons_count) SELECT 'Git & Team Collaboration','Git والعمل ضمن الفريق','Git و کاری تیمی','Git û karê tîmê','Learn Git workflows and collaborate safely on software projects.','تعلّمي Git والعمل الجماعي وإدارة التغييرات في مشاريع البرمجيات.','Git و کاری تیمی و بەڕێوەبردنی گۆڕانکارییەکان فێربە.','Git û karê tîmê û rêvebirina guhertinan fêr bibe.','Branches, commits, pull requests, resolving conflicts and a team workflow project.','الفروع وعمليات الحفظ وطلبات الدمج وحل التعارضات وسير عمل جماعي عملي.','branch وcommit وpull request و چارەسەرکردنی conflict فێربە.','branch, commit, pull request û çareserkirina conflict fêr bibe.','Beginner','free',0,9 FROM (SELECT 1) AS seed WHERE NOT EXISTS (SELECT 1 FROM courses WHERE title_en='Git & Team Collaboration');
INSERT INTO courses (title_en,title_ar,title_ckb,title_badini,description_en,description_ar,description_ckb,description_badini,long_description_en,long_description_ar,long_description_ckb,long_description_badini,level,type,price_iqd,lessons_count) SELECT 'Networking Fundamentals','أساسيات الشبكات','بنەماکانی تۆڕ','Bingehên torê','Understand how networks, IP addresses, DNS and common services work.','افهمي أساسيات الشبكات وعناوين IP وDNS والخدمات الشائعة.','بنەماکانی تۆڕ و IP وDNS و خزمەتگوزارییە باوەکان تێبگە.','Bingehên torê, IP, DNS û xizmetgohên hevpar fêm bike.','A beginner-friendly introduction to networking concepts with practical troubleshooting exercises.','پێشەکییەکی ئاسان بۆ تۆڕ و ڕاهێنانی کرداری بۆ دۆزینەوەی کێشەکان.','پێشەکییەکی دەستپێکەرانە بۆ تۆڕ لەگەڵ ڕاهێنانی چارەسەرکردنی کێشە.','Destpêkek ji bo torê bi rahênanên çareserkirina pirsgirêkan.','Beginner','mixed',18000,10 FROM (SELECT 1) AS seed WHERE NOT EXISTS (SELECT 1 FROM courses WHERE title_en='Networking Fundamentals');
INSERT INTO courses (title_en,title_ar,title_ckb,title_badini,description_en,description_ar,description_ckb,description_badini,long_description_en,long_description_ar,long_description_ckb,long_description_badini,level,type,price_iqd,lessons_count) SELECT 'AI Tools for Everyday Work','أدوات الذكاء الاصطناعي للعمل اليومي','ئامرازەکانی AI بۆ کاری ڕۆژانە','Amûrên AI ji bo karê rojane','Use AI tools responsibly for research, writing, organization and productivity.','استخدمي أدوات الذكاء الاصطناعي بفعالية وأمان في البحث والكتابة وتنظيم العمل.','ئامرازەکانی AI بە شێوەیەکی بەرپرسیارانە بۆ توێژینەوە و نووسین و ڕێکخستنی کار بەکاربهێنە.','Amûrên AI bi berpirsiyarî ji bo lêkolîn, nivîsîn û rêkxistina kar bi kar bîne.','Prompting, verification, privacy, document workflows and a practical productivity project.','التوجيهات، التحقق من النتائج، الخصوصية، سير عمل المستندات ومشروع إنتاجية عملي.','prompting و پشتڕاستکردنەوە و تایبەتمەندی و workflow ـی بەڵگەنامەکان فێربە.','prompting, piştrastkirin, taybetmendî û workflowên belgeyan fêr bibe.','Beginner','free',0,8 FROM (SELECT 1) AS seed WHERE NOT EXISTS (SELECT 1 FROM courses WHERE title_en='AI Tools for Everyday Work');
INSERT INTO courses (title_en,title_ar,title_ckb,title_badini,description_en,description_ar,description_ckb,description_badini,long_description_en,long_description_ar,long_description_ckb,long_description_badini,level,type,price_iqd,lessons_count) SELECT 'Data Analysis with Excel & SQL','تحليل البيانات باستخدام Excel وSQL','شیکاری داتا بە Excel وSQL','Şîroveya daneyan bi Excel û SQL','Turn spreadsheets and databases into clear, useful insights.','حوّلي الجداول وقواعد البيانات إلى معلومات واضحة تساعد على اتخاذ القرار.','Spreadsheet و داتاگاکان بکە بە تێڕوانینی ڕوون و بەسوود.','Spreadsheet û database bibe agahiyên zelal û bikêr.','Clean data, write SQL queries, build simple summaries and communicate findings.','تنظيف البيانات وكتابة استعلامات SQL وبناء ملخصات بسيطة وعرض النتائج بوضوح.','پاککردنەوەی داتا و نووسینی SQL و دروستکردنی پوختە و پیشاندانی ئەنجام فێربە.','Paqijkirina daneyan, nivîsandina SQL, kurtkirin û nîşandana encaman fêr bibe.','Intermediate','paid',40000,13 FROM (SELECT 1) AS seed WHERE NOT EXISTS (SELECT 1 FROM courses WHERE title_en='Data Analysis with Excel & SQL');
